// CONTRAT D'APPARIEMENT — ajouté le 04/09/2026.
// L'analyse IA est recollée au prospect par son INDEX. Si le nœud IA
// produit un nombre d'items différent du SQL, l'analyse d'un prospect est
// attribuée à un autre, silencieusement. On échoue bruyamment.
const sql = $('SQL_Get_Prospects').all();
if (sql.length !== items.length) {
  throw new Error('Appariement impossible : ' + items.length + ' reponses IA pour ' + sql.length + ' prospects.');
}

const PRIORITES = ['1 - Haute', '2 - Moyenne', '3 - Basse'];

return items.map((item, index) => {
  const ai = { angle: '', accroche: '', priorite: '', anomalie: '' };

  try {
    let text = item.json.content.find(c => c.type === 'text').text;
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // MESURE DU 04/09/2026 : un prospect sur cinq a echoue au parsing et
    // une ligne vide est partie dans le Sheet du client. Le modele ajoute
    // parfois une phrase avant ou apres le JSON. On extrait donc le premier
    // objet complet du texte au lieu d'exiger que TOUT le texte soit du JSON.
    const debut = text.indexOf('{');
    const fin = text.lastIndexOf('}');
    if (debut !== -1 && fin > debut) text = text.slice(debut, fin + 1);

    const parsed = JSON.parse(text);
    ai.angle = parsed.angle || '';
    ai.accroche = parsed.accroche || '';
    ai.priorite = parsed.priorite || '';
  } catch (e) {
    ai.anomalie = 'parsing';
  }

  if (!PRIORITES.includes(ai.priorite)) {
    ai.anomalie = ai.anomalie || 'priorite_hors_referentiel';
    ai.priorite = '2 - Moyenne';
  }

  // Une ligne sans angle ni accroche n'a aucune valeur pour la cliente.
  // On le dit dans la cellule plutot que de livrer du vide muet.
  if (!ai.angle && !ai.accroche) {
    ai.angle = 'A REPRENDRE - analyse IA indisponible';
    ai.anomalie = ai.anomalie || 'reponse_vide';
  }

  return { json: { ...sql[index].json, ...ai } };
});
